import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const p=JSON.parse('{"title":"好诗相伴03｜见万物：世间万物在诗中","description":"","frontmatter":{},"headers":[],"relativePath":"如何读懂一首诗/好诗相伴03｜见万物：世间万物在诗中.md","filePath":"如何读懂一首诗/好诗相伴03｜见万物：世间万物在诗中.md","lastUpdated":1779819710000}'),n={name:"如何读懂一首诗/好诗相伴03｜见万物：世间万物在诗中.md"};function E(r,e,o,g,c,b){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="好诗相伴03-见万物-世间万物在诗中" tabindex="-1">好诗相伴03｜见万物：世间万物在诗中 <a class="header-anchor" href="#好诗相伴03-见万物-世间万物在诗中" aria-label="Permalink to &quot;好诗相伴03｜见万物：世间万物在诗中&quot;">​</a></h1><p>好诗相伴，千金不换。你好，我是天博。</p><p>今天我们的“好诗相伴”栏目，录的是“见万物”。我们在“见万物”里说的是诗词里的意象，讲了山水、花朵还有长安和美人这四种意象。</p><p>讲第一个意象 <a href="https://time.geekbang.org/column/article/394129" target="_blank" rel="noreferrer">山水</a> 的时候，我们主要讲了王维的代表作《辋川闲居赠裴秀才迪》，还顺带提到了救了他一命的《凝碧池》，最后在煮酒论诗里分享了他的《积雨辋川庄作》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/5c8fcf777501c451d848bae2483bd287.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/5c8fcf777501c451d848bae2483bd287.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/680762cb75a8cc2e3c3b0620e5bebf42.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/680762cb75a8cc2e3c3b0620e5bebf42.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/788c6b28c3e70053181ae3fc864706ea.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/788c6b28c3e70053181ae3fc864706ea.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/395276" target="_blank" rel="noreferrer">花</a> 的时候，我们讲的是梅花诗，主要讲了刘克庄的《落梅》，还有提到了谢枋得的《武夷山中》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/a7d1e123a727bf095991866fa222a51a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/a7d1e123a727bf095991866fa222a51a.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/91f1111690eb19e37fabff6f118a29ee.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/91f1111690eb19e37fabff6f118a29ee.jpg" alt=""></a></p><p>在讲第三种意象 <a href="https://time.geekbang.org/column/article/396044" target="_blank" rel="noreferrer">长安</a> 的时候，我们主要讲的是柳永的《少年游·长安古道马迟迟》，讲柳永经历的时候提到了他的《望海潮·东南形胜》、还有《鹤冲天·黄金榜上》，最后在煮酒论诗里讲到了李颀讲长安的一首诗，《送魏万之京》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/bf6f2f1591123d475d7044fa15f959a4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/bf6f2f1591123d475d7044fa15f959a4.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/4abe9c7c4eaefa4f126a0682a99bef5f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/4abe9c7c4eaefa4f126a0682a99bef5f.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/fc3857395ed51f25d111439ff22b1995.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/fc3857395ed51f25d111439ff22b1995.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/cc819e2e2bcfd4e681b6e710fdabc108.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/cc819e2e2bcfd4e681b6e710fdabc108.jpg" alt=""></a></p><p>最后在讲 <a href="https://time.geekbang.org/column/article/397002" target="_blank" rel="noreferrer">美人</a> 的时候，我主要讲的是温庭筠的《菩萨蛮·小山重叠金明灭》，还讲了几首古代男性诗人为什么学女子说话写的诗，包括朱庆馀的干谒诗《近试上张籍水部》，张籍回给他的《酬朱庆馀》，还有张籍用来拒绝李师道的《节妇吟·寄东平李司空师道》。</p><p>讲完了这些诗，最后，我在煮酒论诗里分享了李商隐自比女性的《无题·八岁偷照镜》</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/25578b3f6f6cdb28d8d7c61e59c5a46a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/25578b3f6f6cdb28d8d7c61e59c5a46a.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/8d20d99d7fc527d13ccf349bc54aca73.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/8d20d99d7fc527d13ccf349bc54aca73.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/a73c7a72ac06a9415d0e363d33ddfe45.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/a73c7a72ac06a9415d0e363d33ddfe45.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/8ea6d9321b12640e645aa1b9db3a0841.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/8ea6d9321b12640e645aa1b9db3a0841.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/cfeca91a98d1b22b989178e03d391aee.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417793/cfeca91a98d1b22b989178e03d391aee.jpg" alt=""></a></p><p>到这里，我们今天的好诗相伴就结束了。如果这里面有你喜欢的诗，欢迎你多听两遍，也欢迎你把这些诗分享给自己的朋友，我们下一讲再见。</p>',23)])])}const f=t(n,[["render",E]]);export{p as __pageData,f as default};
